// KPIs for last week vs the week before
// Sales columns: date, region, product, channel, quantity, revenue, cost
// Expenses columns: date, category, amount
const DAY = 86400000;
const now = new Date(); now.setHours(0, 0, 0, 0);
const mondayThis = new Date(now.getTime() - ((now.getDay() + 6) % 7) * DAY);
const start = new Date(mondayThis.getTime() - 7 * DAY), end = mondayThis;
const pStart = new Date(start.getTime() - 7 * DAY), pEnd = start;
const n = v => Number(String(v ?? 0).replace(/[^0-9.\-]/g, '')) || 0;
const inRange = (d, a, b) => { const t = new Date(d); return t >= a && t < b; };
const sales = $('Read Sales').all().map(i => i.json).filter(r => r.date);
const exps = $('Read Expenses').all().map(i => i.json).filter(r => r.date);
const cur = sales.filter(r => inRange(r.date, start, end));
const prev = sales.filter(r => inRange(r.date, pStart, pEnd));
const sum = (arr, f) => arr.reduce((s, r) => s + n(r[f]), 0);
const group = (arr, key, f) => { const g = {}; for (const r of arr) g[r[key] || 'Other'] = (g[r[key] || 'Other'] || 0) + n(r[f]); return Object.entries(g).sort((a, b) => b[1] - a[1]); };
const revenue = sum(cur, 'revenue'), revenuePrev = sum(prev, 'revenue');
const cogs = sum(cur, 'cost');
const curExp = exps.filter(r => inRange(r.date, start, end));
const opex = sum(curExp, 'amount');
const grossProfit = revenue - cogs;
const netResult = grossProfit - opex;
const pct = (a, b) => b ? Number((((a - b) / b) * 100).toFixed(1)) : null;
return [{ json: {
  period: `${start.toISOString().slice(0, 10)} to ${new Date(end.getTime() - DAY).toISOString().slice(0, 10)}`,
  revenue, revenuePrev, revenueChangePct: pct(revenue, revenuePrev),
  orders: cur.length, ordersPrev: prev.length,
  avgOrder: cur.length ? Number((revenue / cur.length).toFixed(2)) : 0,
  grossProfit, grossMarginPct: revenue ? Number(((grossProfit / revenue) * 100).toFixed(1)) : 0,
  opex, netResult,
  topProducts: group(cur, 'product', 'revenue').slice(0, 5),
  byRegion: group(cur, 'region', 'revenue'),
  byChannel: group(cur, 'channel', 'revenue'),
  expensesByCategory: group(curExp, 'category', 'amount').slice(0, 6)
}}];

// Build the HTML email
const k = $('Calculate KPIs').first().json;
let summary = $input.first().json?.choices?.[0]?.message?.content || '<ul><li>Summary unavailable this week. Figures below are complete.</li></ul>';
const money = v => Number(v || 0).toLocaleString('tr-TR', { minimumFractionDigits: 0, maximumFractionDigits: 0 }) + ' ₺';
const chg = v => v === null ? '-' : `<span style="color:${v >= 0 ? '#1d7a4c' : '#b03a2e'}">${v >= 0 ? '+' : ''}${v}%</span>`;
const rows = arr => arr.map(([name, val]) => `<tr><td style="padding:4px 10px;border-bottom:1px solid #eee">${name}</td><td style="padding:4px 10px;border-bottom:1px solid #eee;text-align:right">${money(val)}</td></tr>`).join('');
const card = (label, value, sub = '') => `<td style="padding:10px 14px;background:#f5f7f9;border-radius:6px"><div style="font-size:12px;color:#5a6876">${label}</div><div style="font-size:18px;font-weight:700">${value}</div><div style="font-size:12px">${sub}</div></td>`;
const html = `<div style="font-family:Segoe UI,Arial,sans-serif;max-width:640px;color:#16202a">
<h2 style="margin:0 0 4px">Weekly Sales & Finance Report</h2>
<div style="color:#5a6876;margin-bottom:16px">${k.period}</div>
<table cellspacing="8"><tr>${card('Revenue', money(k.revenue), chg(k.revenueChangePct) + ' vs prior week')}${card('Gross margin', k.grossMarginPct + '%', money(k.grossProfit))}${card('Net result', money(k.netResult), 'after ' + money(k.opex) + ' opex')}</tr></table>
<h3>Summary</h3>${summary}
<h3>Top products</h3><table style="border-collapse:collapse;width:100%">${rows(k.topProducts)}</table>
<h3>Revenue by region</h3><table style="border-collapse:collapse;width:100%">${rows(k.byRegion)}</table>
<h3>Expenses by category</h3><table style="border-collapse:collapse;width:100%">${rows(k.expensesByCategory)}</table>
<p style="color:#5a6876;font-size:12px;margin-top:20px">Orders: ${k.orders} (prior week ${k.ordersPrev}) · Avg order: ${money(k.avgOrder)} · Generated automatically by n8n</p></div>`;
return [{ json: { html, subject: `Weekly report ${k.period}: revenue ${money(k.revenue)} (${k.revenueChangePct ?? '-'}%)`, ...k } }];

